import React, { useContext, useState } from "react";
import GeneralContext from "./GeneralContext";

const BuyActionWindow = ({ uid, type }) => {
  const { closeTradeWindow } = useContext(GeneralContext);
  const [quantity, setQuantity] = useState("");
  const [price, setPrice] = useState("");

  const handleConfirm = () => {
    console.log(`Executing ${type.toUpperCase()} for ${uid}`);
    console.log(`Quantity: ${quantity}, Price: ${price}`);

    // Example: send to backend
    // axios.post("/api/trade", { uid, type, quantity, price });

    closeTradeWindow();
  };

  return (
    <div className="buy-action-window">
      <h2>{type === "buy" ? "Buy Stock" : "Sell Stock"}</h2>
      <p>Stock: {uid}</p>

      <input
        type="number"
        placeholder="Quantity"
        value={quantity}
        onChange={(e) => setQuantity(e.target.value)}
      />
      <input
        type="number"
        placeholder="Price"
        value={price}
        onChange={(e) => setPrice(e.target.value)}
      />

      <div className="buttons">
        <button onClick={handleConfirm} className={type === "buy" ? "buy" : "sell"}>
          {type.toUpperCase()}
        </button>
        <button onClick={closeTradeWindow}>Cancel</button>
      </div>
    </div>
  );
};

export default BuyActionWindow;
